	private static class RecordingSource extends AbstractCloseableIteration<BindingSet>
			implements CooperativeCancellation {
		private final Iterator<? extends BindingSet> rows;
		private final boolean acceptsCancellation;
		int nextCalls;
		int closeCalls;
		int cancelRequests;

		RecordingSource(List<? extends BindingSet> rows, boolean acceptsCancellation) {
			this.rows = rows.iterator();
			this.acceptsCancellation = acceptsCancellation;
		}

		@Override
		public boolean hasNext() {
			return rows.hasNext();
		}

		@Override
		public BindingSet next() {
			nextCalls++;
			return rows.next();
		}

		@Override
		public boolean requestCancellation() {
			cancelRequests++;
			return acceptsCancellation;
		}

		@Override
		protected void handleClose() {
			closeCalls++;
		}
	}
